begin;

with input_items as (
  select *
  from jsonb_to_recordset('[]'::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset('[{"id": "87cef2ac-8eb1-5b84-9c21-b85affe9b985", "feature_slug": "event-order-consumers", "title": "1. CurrencyConsumer", "content": "### File\n`src/consumers/currency-consumer.ts` (or equivalent)\n\n### Current behaviour\nFilters `purchase_ledger` CDC events to `status = ''completed''` only before processing currency awards.\n\n### Change required\n\nIn the `shouldProcess` / filter logic, add a second routing path:\n\n```typescript\n// Existing path (unchanged):\nif (record.status === ''completed'') {\n  return true;\n}\n\n// New path — pending event orders:\nif (\n  record.status === ''pending'' &&\n  record.transaction_source === ''event_order''\n) {\n  return true;\n}\n\nreturn false;\n```\n\n### Processing logic for pending event orders\n\nWhen processing a pending event order, the consumer must **only** evaluate earn_factor_groups whose linked `earn_conditions_group.allowed_purchase_statuses` includes `''pending''`.\n\nPseudo-logic:\n\n```typescript\n// When status === ''pending'' && transaction_source === ''event_order'':\n// 1. Load earn_factor_groups for the merchant that are active and within window\n// 2. For each group, load its earn_factors and their earn_conditions_group\n// 3. Skip the group if earn_conditions_group.allowed_purchase_statuses\n//    does NOT include ''pending'' (or is NULL)\n// 4. Run normal currency calc for qualifying groups only\n// 5. Call post_wallet_transaction as normal\n```\n\nThe `allowed_purchase_statuses` column is on `earn_conditions_group` (added by migration `event_ordering_schema_additions`). Query it alongside normal earn factor loading.\n\n### Why this is safe\n- NULL `allowed_purchase_statuses` → skip (default, existing groups unaffected)\n- Only explicitly opted-in earn_conditions_groups fire on pending\n- Completed orders still go through the original path and evaluate all groups normally\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/feature-docs/Event_Order_Consumer_Changes.md#L13 1. CurrencyConsumer", "metadata": {"source_doc_type": "implementation_note", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "event-order-consumers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "de5fd6f6fbf0037a1ad759b55189ecc1aafca0668f4d6ef9bd87477a998f08b2", "truncated": false}, "is_active": true}, {"id": "d399e453-ddc3-5f4e-b957-8bf1044d524d", "feature_slug": "event-order-consumers", "title": "2. AmpConsumer", "content": "### File\n`src/consumers/amp-consumer.ts` (or equivalent)\n\n### Current behaviour\nIn `shouldDispatch()` for `purchase_ledger` table: only dispatches when `record.status === ''completed''`.\n\n### Change required\n\nAdd one additional condition:\n\n```typescript\n// Existing (unchanged):\nif (table === ''purchase_ledger'' && record.status === ''completed'') {\n  return true;\n}\n\n// New:\nif (\n  table === ''purchase_ledger'' &&\n  record.status === ''pending'' &&\n  record.transaction_source === ''event_order''\n) {\n  return true;\n}\n```\n\n### Field mapping for dispatch payload\n\nWhen routing a pending event order, ensure `transaction_source_id` is included in `extractRecordData()` so the `dispatch-workflow-trigger` edge function can match `amp_workflow_trigger.trigger_conditions` (which merchants use to scope workflows to a specific event via `{ \"transaction_source_id\": \"<event_uuid>\" }`).\n\n```typescript\n// In extractRecordData for purchase_ledger:\n{\n  trigger_table: ''purchase_ledger'',\n  trigger_operation: ''INSERT'',\n  merchant_id: record.merchant_id,\n  user_id: record.user_id,\n  record_id: record.id,\n  record_data: {\n    status: record.status,\n    transaction_source: record.transaction_source,\n    transaction_source_id: record.transaction_source_id,  // ← ensure this is included\n    final_amount: record.final_amount,\n    api_source: record.api_source,\n  }\n}\n```\n\n### No other changes needed\n`dispatch-workflow-trigger` and `inngest-serve` require no changes — they already handle the routing and the updated `fn_execute_amp_action` (with `push_reward`) is live in Supabase.\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/feature-docs/Event_Order_Consumer_Changes.md#L67 2. AmpConsumer", "metadata": {"source_doc_type": "implementation_note", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "event-order-consumers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "1fe0a1ebeeef2e70fe200cdd9e70f25ec185e8959ebb122fa8b1ace2887e285c", "truncated": false}, "is_active": true}, {"id": "6b4f709b-1196-521c-9cf6-c72852dc8769", "feature_slug": "event-order-consumers", "title": "Deployment", "content": "1. Deploy Supabase migrations first (already done)\n2. Deploy `crm-event-processors` with both consumer changes\n3. No other services require changes", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "technical"], "output_uses": ["implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/feature-docs/Event_Order_Consumer_Changes.md#L122 Deployment", "metadata": {"source_doc_type": "implementation_note", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "event-order-consumers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "229d019dd233513b67bdc57026682392be4e3b2be89fa94e500c559aa2b898ca", "truncated": false}, "is_active": true}, {"id": "298e591e-6eb5-5d1d-b6d5-13a0031c2fac", "feature_slug": "event-order-consumers", "title": "Testing", "content": "### CurrencyConsumer test\n1. Create an earn_conditions_group with `allowed_purchase_statuses = [''pending'']`\n2. Link an earn_factor to it\n3. Call `api_create_manual_purchase_order` with `transaction_source=''event_order''`\n4. Verify `wallet_ledger` entry created for the pending purchase\n5. Verify completed purchases still process normally (regression check)\n\n### AmpConsumer test\n1. Create an AMP workflow with trigger on `purchase_ledger INSERT`, trigger_conditions `{ \"transaction_source_id\": \"<event_id>\", \"status\": \"pending\" }`\n2. Add a `push_reward` action node\n3. Call `api_create_manual_purchase_order` with `transaction_source=''event_order''`\n4. Verify `reward_redemptions_ledger` entry created for the user", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["technical", "testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/Event_Order_Consumer_Changes.md#L128 Testing", "metadata": {"source_doc_type": "implementation_note", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "event-order-consumers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "6ffb11b17c9362be07e72927b659f591080598ebe55047984878f1313fa9bb9e", "truncated": false}, "is_active": true}, {"id": "cec72e20-b020-50e3-ab6d-a31b8ca5c39e", "feature_slug": "event-promo-engine", "title": "Condition Types", "content": "Conditions are stored as JSONB on `event_promo_rule.condition_definition`. Four types compose recursively.\n\n### 1. `product_qty_threshold`\n\nPasses when a specific SKU in the order meets a minimum quantity.\n\n```json\n{\n  \"type\": \"product_qty_threshold\",\n  \"sku_code\": \"PLENUM\",\n  \"min_qty\": 5\n}\n```\n\nOptional `size_filter`: matched against `purchase_items_ledger.variant_name` using case-insensitive ILIKE.\n\n```json\n{\n  \"type\": \"product_qty_threshold\",\n  \"sku_code\": \"REFLEX-EVO-500\",\n  \"min_qty\": 2,\n  \"size_filter\": \"500cc\"\n}\n```\n\n### 2. `product_combo`\n\nPasses when ALL specified products each meet their own minimum quantity. When `scalable: true`, the outcome quantity scales with the number of sets achievable.\n\n```json\n{\n  \"type\": \"product_combo\",\n  \"scalable\": true,\n  \"items\": [\n    { \"sku_code\": \"REFLEX-EVO-500\", \"min_qty\": 2, \"size_filter\": \"500cc\" },\n    { \"sku_code\": \"AMURE-500\",      \"min_qty\": 2, \"size_filter\": \"500cc\" },\n    { \"sku_code\": \"ORTIVA-500\",     \"min_qty\": 2, \"size_filter\": \"500cc\" }\n  ]\n}\n```\n\nSet count = `floor(min(qty_i / min_qty_i))` across all items.\n\n### 3. `spend_threshold`\n\nPasses when `purchase_ledger.final_amount` meets a minimum.\n\n```json\n{ \"type\": \"spend_threshold\", \"min_spend\": 3500 }\n```\n\n### 4. `compound`\n\nRecursive AND/OR over child conditions (any of the above types, nested).\n\n```json\n{\n  \"type\": \"compound\",\n  \"operator\": \"AND\",\n  \"items\": [\n    { \"type\": \"product_qty_threshold\", \"sku_code\": \"ISABION\", \"min_qty\": 1 },\n    {\n      \"type\": \"compound\",\n      \"operator\": \"OR\",\n      \"items\": [\n        { \"type\": \"product_qty_threshold\", \"sku_code\": \"BREXIL-MULTI\", \"min_qty\": 1 },\n        { \"type\": \"product_qty_threshold\", \"sku_code\": \"BREXIL-CALBO\", \"min_qty\": 1 }\n      ]\n    }\n  ]\n}\n```\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "qa_testing", "technical_docs"], "scope": "general", "source_ref": "requirements/feature-docs/Event_Promo_Engine.md#L63 Condition Types", "metadata": {"source_doc_type": "domain_reference", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "event-promo-engine", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "2f11482743bce09a6dc6605e4b05d10f5dcdc2aac70ca9e0498e15b424c5fecb", "truncated": false}, "is_active": true}, {"id": "fe4d6619-3b10-50df-938f-0a4a68b4dd74", "feature_slug": "event-promo-engine", "title": "Promo Structure", "content": "### `event_promo` (header)\n\n| Column | Notes |\n|---|---|\n| `event_id` | FK → `syngenta_events_master.id`. NOT NULL. |\n| `name`, `description` | Display fields. |\n| `eval_mode` | `''highest''`: pick best (highest `rule_order`) qualifying rule only. `''all''`: apply every qualifying rule. |\n| `max_claims_per_user` | INT. NULL = unlimited. For scalable combo promos, this is the cap on set count. |\n| `sort_order` | Evaluation order across promos for the same event. |\n| `is_active` | Standard boolean. |\n\n### `event_promo_rule` (detail)\n\n| Column | Notes |\n|---|---|\n| `promo_id` | FK → `event_promo.id` ON DELETE CASCADE. |\n| `rule_order` | Ascending. Higher value = better outcome. Used by `eval_mode=''highest''`. |\n| `rule_name` | Display label, e.g. \"≥5 pieces\", \"Spend 5,000 THB\". |\n| `condition_definition` | JSONB. See condition types below. |\n| `outcome_type` | `''freebie''`, `''bill_discount_pct''`, `''bill_discount_fixed''`. |\n| `outcome_sku_id` | FK → `product_sku_master.id`. NULL for custom freebies. |\n| `outcome_sku_code`, `outcome_product_name`, `outcome_variant_name` | Always stored explicitly. For master: populated at config time from master. For custom: entered inline. |\n| `outcome_quantity` | Fixed quantity for non-scalable rules. |\n| `outcome_scalable` | Boolean. If true: quantity = floor(set_count), capped by `max_claims_per_user`. |\n| `outcome_discount_pct` | For `bill_discount_pct`: percentage (e.g. `5` = 5%). |\n| `outcome_discount_fixed` | For `bill_discount_fixed`: fixed THB amount. |\n\n### `event_promo_claim` (usage tracking)\n\n| Column | Notes |\n|---|---|\n| `promo_id`, `rule_id` | What fired. |\n| `user_id`, `transaction_id` | Who and which order. |\n| `quantity_claimed` | For scalable promos: actual set count. |\n| UNIQUE(`promo_id`, `user_id`, `transaction_id`) | One claim record per promo per order per user. |\n\n---", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["implementation", "technical"], "output_uses": ["implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/feature-docs/Event_Promo_Engine.md#L23 Promo Structure", "metadata": {"source_doc_type": "domain_reference", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "event-promo-engine", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5fc87e533bd1e8bc4d99be44c6b1d8d9f8e07bc6ebc35631ada10e53fbf1069d", "truncated": false}, "is_active": true}, {"id": "c9ecd0af-3ac1-5ff2-bde3-856f984624e1", "feature_slug": "event-promo-engine", "title": "Admin BFF Functions", "content": "| Function | Purpose | Permission |\n|---|---|---|\n| `bff_upsert_event_promo_with_rules(p_promo_id, p_event_id, ..., p_rules[])` | Create/update promo + rules atomically | `manage_events` |\n| `bff_get_event_promo_details(p_promo_id, p_mode)` | `''new''` = empty template, `''edit''` = promo + rules | authenticated |\n| `bff_list_event_promos(p_event_id)` | List with rule count and total claims | authenticated |\n| `bff_delete_event_promo(p_promo_id)` | Delete promo + cascade rules + claims | `manage_events` |\n| `bff_preview_event_promos(p_event_id, p_user_id, p_amount, p_items)` | Read-only promo preview | authenticated |\n\nAll BFF functions: `SECURITY DEFINER`, `get_current_merchant_id()` first, `fn_response_success` / `fn_response_error` returns.\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/feature-docs/Event_Promo_Engine.md#L257 Admin BFF Functions", "metadata": {"source_doc_type": "domain_reference", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "event-promo-engine", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "f14af91b5cc53c3f91a527bff07004b79c95f395a90181f8dc1c3334249b5d11", "truncated": false}, "is_active": true}, {"id": "a555dbe4-7d67-5fbd-9213-5013b9e548bc", "feature_slug": "event-promo-engine", "title": "Internal Functions", "content": "| Function | Security | Purpose |\n|---|---|---|\n| `fn_evaluate_promo_condition(condition_def, items, final_amount)` | INVOKER | Recursive JSONB condition evaluator |\n| `fn_calc_event_promos(merchant_id, event_id, user_id, final_amount, items)` | INVOKER | Read-only promo calculation |\n| `fn_apply_event_promos(merchant_id, transaction_id, user_id, promo_result)` | INVOKER | Write freebies + discounts + claims |\n\n---\n\n*Document Version: 1.0*\n*Created: April 25, 2026*\n*System: Supabase CRM — Event Promo Engine (Freebies + Bill Discounts)*", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/feature-docs/Event_Promo_Engine.md#L271 Internal Functions", "metadata": {"source_doc_type": "domain_reference", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "event-promo-engine", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ec0f358ab42838a2dd322b65f7e9a40682c07700d7a25bc0eb1192fb9551b67d", "truncated": false}, "is_active": true}, {"id": "2d7fa908-8bf7-5929-bbdb-c4e4044c3ff4", "feature_slug": "event-promo-engine", "title": "Concepts", "content": "| Term | Definition |\n|---|---|\n| **Promo** (`event_promo`) | A promotion associated with one event. Has evaluation mode and per-user claim limit. |\n| **Rule** (`event_promo_rule`) | One condition + one outcome within a promo. Multi-rule promos represent escalating tiers. |\n| **Condition** | JSONB definition of what must be true in the order to trigger the outcome. |\n| **Outcome** | What the customer gets: a freebie item or a bill-level discount. |\n| **Claim** (`event_promo_claim`) | Record of a promo outcome being triggered for a user on a specific order. Used for per-user limit enforcement. |\n\n---", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/Event_Promo_Engine.md#L11 Concepts", "metadata": {"source_doc_type": "domain_reference", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "event-promo-engine", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "87e5c39eaaf1e0c2e4143b6e1c42ae043a6be692030b0a1bebaf22866b3213f0", "truncated": false}, "is_active": true}, {"id": "8982cbd5-6821-5d1a-964c-cf899d31bbaa", "feature_slug": "event-promo-engine", "title": "Overview", "content": "The Event Promo Engine calculates and applies promotional outcomes (freebies and bill-level discounts) to event orders **synchronously at order creation**. It is completely separate from the currency earning pipeline (which is event-driven).\n\n**Scope**: Promos are configured per event (`syngenta_events_master`). Each promo has one or more rules, each with a condition and an outcome.\n\n---", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/Event_Promo_Engine.md#L3 Overview", "metadata": {"source_doc_type": "domain_reference", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "event-promo-engine", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "38698bb3d7ff79e887c0e07cb03e7eec2653cf48c32b31392e127e99318f3137", "truncated": false}, "is_active": true}, {"id": "e688bdc2-fa5c-5468-9c84-670fc7b9401f", "feature_slug": "event-promo-engine", "title": "Evaluation Algorithm", "content": "`fn_calc_event_promos(merchant_id, event_id, user_id, final_amount, items)`:\n\n1. Load active promos for the event ordered by `sort_order`\n2. For each promo:\n   a. Count existing claims for this user (`event_promo_claim`). Skip promo if at `max_claims_per_user`\n   b. Evaluate rules from highest `rule_order` down:\n      - Call `fn_evaluate_promo_condition(condition_definition, items, final_amount)` (recursive)\n      - `eval_mode=''highest''`: take first passing rule, break\n      - `eval_mode=''all''`: collect all passing rules\n   c. For passing rules: compute effective outcome quantity\n      - Non-scalable: `outcome_quantity` (fixed)\n      - Scalable: `floor(min_set_count)`, capped at `max_claims_per_user - already_claimed`\n3. Return `{freebies[], bill_discounts[], total_bill_discount, adjusted_final_amount}`\n\n`fn_apply_event_promos(merchant_id, transaction_id, user_id, promo_result)`:\n1. Insert freebie rows into `purchase_items_ledger` with `item_type=''freebie''`, `unit_price=0`\n2. Update `purchase_ledger.discount_amount` and `final_amount` for bill discounts\n3. Insert `event_promo_claim` rows\n4. Write `purchase_ledger.reward_list` (the full result JSONB)\n\nBoth called within the same transaction as `api_create_manual_purchase_order`.\n\n---", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/feature-docs/Event_Promo_Engine.md#L140 Evaluation Algorithm", "metadata": {"source_doc_type": "domain_reference", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "event-promo-engine", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ba6fa2fab9658b0298f0be24092aa36988e9da533f14098d79978f8754c33f09", "truncated": false}, "is_active": true}, {"id": "98d357db-c353-518f-8402-52b081156c9b", "feature_slug": "event-promo-engine", "title": "Freebie Source: Master vs Custom", "content": "When configuring a promo rule outcome, admin picks one of two paths:\n\n**Master product**: Select from `product_sku_master`. `outcome_sku_id` is populated. Name/variant/code copied from master into the rule row at config time.\n\n**Custom freebie**: Enter name, code, variant inline on the rule. `outcome_sku_id = NULL`. The freebie exists only as a line item description — it does not exist in `product_sku_master` or `event_product_config`.\n\nIn both cases `outcome_sku_code`, `outcome_product_name`, and `outcome_variant_name` are always stored directly on the rule row, so freebie line items can be created without any additional joins.\n\n---", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/feature-docs/Event_Promo_Engine.md#L245 Freebie Source: Master vs Custom", "metadata": {"source_doc_type": "domain_reference", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "event-promo-engine", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "6765eb8d9d0043d0bd55c0c87e80ef500cb95aa5514f58a2014e2c84d1b576c5", "truncated": false}, "is_active": true}, {"id": "e058ede1-07f7-5840-8630-335a1842f334", "feature_slug": "event-promo-engine", "title": "Promo Examples (from Syngenta Use Case)", "content": "### Promo 1: Reflex Evo + Amure + Ortiva combo\n\n**Config:**\n- `event_promo`: `eval_mode=''highest''`, `max_claims_per_user=2`\n- `event_promo_rule` (1 row): condition = `product_combo` (3 items, each min_qty=2, 500cc); `outcome_scalable=true`; outcome = PTT Voucher 500 THB\n\n**Evaluation example:**\n- Customer orders reflex=2, amure=2, ortiva=2 → set_count = floor(min(1,1,1)) = 1 → 1 voucher\n- Customer orders reflex=4, amure=4, ortiva=4 → set_count = 2 → 2 vouchers (at cap)\n- Customer orders reflex=4, amure=4, ortiva=4 on second order → already_claimed=2, at cap → skipped\n\n---\n\n### Promo 2: Plenum quantity tiers\n\n**Config:**\n- `event_promo`: `eval_mode=''highest''`\n- Rule 1 (`rule_order=1`): condition = `product_qty_threshold` plenum min_qty=5; outcome = Vegetable Oils 5L\n- Rule 2 (`rule_order=2`): condition = `product_qty_threshold` plenum min_qty=10; outcome = Cooking Oils 1L 1 Carton\n\n**Evaluation:** Start from rule_order=2 (highest). plenum=5: rule 2 fails, rule 1 passes → Vegetable Oils. plenum=10: rule 2 passes → Cooking Oils only.\n\n---\n\n### Promo 3: Virtako quantity tiers\n\nSame structure as Promo 2. Two rules with qty thresholds.\n\n---\n\n### Promo 4: Isabion + Brexil compound\n\n**Config:**\n- `event_promo`: `eval_mode=''highest''`\n- Rule 1 (`rule_order=1`): condition = `compound AND [isabion≥1, compound OR [brexil_multi≥1, brexil_calbo≥1]]`; outcome = Vegetable Oil 1L\n\n---\n\n### Promo 5: On-top spend tiers\n\n**Config:**\n- `event_promo`: `eval_mode=''highest''`\n- Rules (5 rows, rule_order 1–5):\n  - rule_order=1: spend≥3,500 → หมวก\n  - rule_order=2: spend≥5,000 → กระติกน้ำแข็ง\n  - rule_order=3: spend≥12,000 → เก้าอี้สนาม\n  - rule_order=4: spend≥24,000 → ชุดหม้อ\n  - rule_order=5: spend≥35,000 → ไฟโซล่าเซลล์\n\n**Evaluation:** 7,200 THB → rule 5 fails, rule 4 fails, rule 3 fails, rule 2 passes → กระติกน้ำแข็ง.\n\n---\n\n### Combined example\n\n**Input:** reflex_evo=2, amure=2, ortiva=2, plenum=5, total_spend=7,200 THB\n\n**Promo 1** fires: PTT Voucher × 1\n**Promo 2** fires: Vegetable Oils 5L × 1 (rule 1 passes, rule 2 fails)\n**Promo 5** fires: กระติกน้ำแข็ง × 1 (rule 2 passes)\n\n**reward_list output:**\n```json\n{\n  \"freebies\": [\n    { \"promo_name\": \"Promo 1: Reflex combo\", \"outcome_product_name\": \"PTT Voucher 500 THB\", \"outcome_quantity\": 1 },\n    { \"promo_name\": \"Promo 2: Plenum\", \"outcome_product_name\": \"Vegetable Oils 5L\", \"outcome_quantity\": 1 },\n    { \"promo_name\": \"Promo 5: On-top Spend\", \"outcome_product_name\": \"กระติกน้ำแข็ง\", \"outcome_quantity\": 1 }\n  ],\n  \"bill_discounts\": [],\n  \"total_bill_discount\": 0,\n  \"adjusted_final_amount\": 7200\n}\n```\n\n---", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["technical", "testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/Event_Promo_Engine.md#L166 Promo Examples (from Syngenta Use Case)", "metadata": {"source_doc_type": "domain_reference", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "event-promo-engine", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "7ffdf4912ae855cfcaaa59c368e7d6f950cca002111cb99ff35a60bf9747c5db", "truncated": false}, "is_active": true}, {"id": "0c53e834-5fb4-5b4c-96e2-acc34afdf5e5", "feature_slug": "event-promotion", "title": "Business Rules", "content": "- Promotions are created at merchant level.\n- Event and activity-group selections are stored in `event_promo_mapping`.\n- Activity-group mappings are stored as activity groups, not expanded into event IDs, so newly created events in the group can inherit the promo.\n- A promo applies when the current event has a direct mapping or its `activity_group` matches a mapped activity group.\n- Total and per-event claim limits are both enforced when present.\n- `eval_mode=''highest''` applies the highest ordered passing rule.\n- `eval_mode=''all''` applies every passing rule until claim limits are exhausted.\n- Outcomes on the same rule are applied in `outcome_order`.\n- Total/per-event claim limits are per-rule budgets. Once a rule budget is exhausted, later outcomes on that rule are skipped.\n- Freebie and free reward outcomes consume the emitted quantity as claim units.\n- Bill discount outcomes consume one claim unit.\n- Promos with existing claims should be deactivated instead of deleted.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Event_Promotion.md#L53 Business Rules", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "event-promotion", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "07bf238030c9c0f43703b09c0187d30a07b7dfc1f15b62a8ba728bd1b70636d4", "truncated": false}, "is_active": true}, {"id": "cede3dc2-c20d-58f7-bf8e-e8314c6eec61", "feature_slug": "event-promotion", "title": "Internal Functions", "content": "- `fn_calc_event_promos(...)`: finds mapped promos, evaluates conditions, loops rule outcomes in `outcome_order`, enforces total/per-event claim limits as per-rule budgets, and returns freebies, bill discounts, rewards, total discount, and adjusted final amount.\n- `fn_apply_event_promos(...)`: inserts freebie line items, records claims with `event_id`, and writes bill discounts to `purchase_ledger`.\n- `fn_evaluate_promo_condition(...)`: evaluates product quantity, spend, combo, and compound conditions.", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Event_Promotion.md#L146 Internal Functions", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "event-promotion", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "7c41b783f5ec74605db96fa7b094b679fa6ce65b369ab8c76ba23aa16ee5ba1b", "truncated": false}, "is_active": true}, {"id": "667036a9-bb7e-568d-aa8e-d7da0fe5c9e9", "feature_slug": "event-promotion", "title": "FE-Callable Functions", "content": "### `bff_list_event_promos(p_event_id uuid DEFAULT NULL)`\n\n- Use `NULL` for the merchant-level promo list page.\n- Pass an event ID to show promos applicable to that event.\n- Returns claim counts, rule counts, mapping counts, applicable event counts, and mappings.\n\n### `bff_get_event_promo_details(p_promo_id uuid, p_mode text DEFAULT ''edit'')`\n\n- `p_mode=''new''` returns an empty promo template.\n- Edit mode returns `{ promo, rules, mappings }`.\n- Each rule includes `outcomes[]` sorted by `outcome_order`.\n- Legacy flat `outcome_*` fields are still returned on the rule and are sourced from `outcomes[0]`.\n\n### `bff_upsert_event_promo_config(p_promo_id uuid DEFAULT NULL, p_promo jsonb DEFAULT ''{}'', p_rules jsonb DEFAULT ''[]'', p_mappings jsonb DEFAULT ''[]'')`\n\nPrimary save function for merchant-level promo management.\n\n`p_rules` item shape:\n\n```json\n{\n  \"rule_order\": 0,\n  \"rule_name\": \"Spend threshold\",\n  \"condition_definition\": { \"type\": \"spend_threshold\", \"min_spend\": 1000 },\n  \"outcomes\": [\n    {\n      \"outcome_type\": \"freebie\",\n      \"outcome_sku_id\": null,\n      \"outcome_sku_code\": \"FREE-SKU\",\n      \"outcome_product_name\": \"Free Product\",\n      \"outcome_variant_name\": \"Default\",\n      \"outcome_quantity\": 1,\n      \"outcome_scalable\": false\n    },\n    {\n      \"outcome_type\": \"bill_discount_pct\",\n      \"outcome_discount_pct\": 10\n    },\n    {\n      \"outcome_type\": \"free_reward\",\n      \"outcome_reward_id\": \"uuid\",\n      \"outcome_reward_name\": \"Free Reward\",\n      \"outcome_quantity\": 1\n    }\n  ]\n}\n```\n\nRules without `outcomes` are treated as legacy payloads and synthesize one outcome from flat `outcome_*` fields. Rules with `outcomes: []` are rejected.\n\n`p_mappings` item shape:\n\n```json\n{ \"mapping_type\": \"event\", \"event_id\": \"uuid\" }\n```\n\n```json\n{ \"mapping_type\": \"activity_group\", \"activity_group\": \"Farmer Meeting\" }\n```\n\n### `bff_upsert_event_promo_with_rules(p_event_id uuid, p_promo_id uuid DEFAULT NULL, p_promo jsonb DEFAULT ''{}'', p_rules jsonb DEFAULT ''[]'')`\n\nLegacy event-level wrapper. It saves one direct event mapping.\n\n### `bff_preview_event_promos(p_event_id uuid, p_user_id uuid, p_final_amount numeric, p_items jsonb)`\n\nRuns the calculator for event order preview.\n\n### `bff_toggle_event_promo(p_promo_id uuid, p_is_active boolean)`\n\nActivates or deactivates a promo.\n\n### `bff_delete_event_promo(p_promo_id uuid)`\n\nDeletes promos that have no claims. Returns `PROMO_HAS_CLAIMS` when claims exist.", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Event_Promotion.md#L68 FE-Callable Functions", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "event-promotion", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "f1f47cae7c8160b4b2dd677ae48fdbfd486ea1f1be98b5841ab543a4ad16d8b3", "truncated": false}, "is_active": true}, {"id": "7688c828-2324-5e0d-ad12-6e44c246935e", "feature_slug": "event-promotion", "title": "Event Promotion Domain Reference", "content": "**Keywords:** event_promo, event_promo_rule, event_promo_rule_outcome, event_promo_mapping, event_promo_claim, event promotion, merchant promo, event promo, activity_group promo, freebie, free reward, bill discount, promo claim limit\n**Source:** `Event_Promotion.md`\n| Function | Parameters | Returns |\n|---|---|---|\n| `bff_list_event_promos(p_event_id?)` | Optional event filter. `NULL` lists merchant-level promos; event ID lists promos directly or activity-group applicable to that event. | Promo rows with rule count, mapping count, applicable event count, claim count, mappings |\n| `bff_get_event_promo_details(p_promo_id, p_mode?)` | `p_mode=''new''` returns empty template; edit mode returns promo, rules with `outcomes[]`, mappings. Legacy flat rule `outcome_*` fields mirror `outcomes[0]`. | `{ promo, rules[], mappings[] }` |\n| `bff_upsert_event_promo_config(p_promo_id?, p_promo, p_rules, p_mappings)` | Merchant-level promo save with nested rules, `rules[].outcomes[]`, and `event_promo_mapping` rows. Missing `outcomes` synthesizes one legacy outcome; empty `outcomes` is rejected. | `{ promo_id }` |\n| `bff_upsert_event_promo_with_rules(p_event_id, p_promo_id?, p_promo, p_rules)` | Legacy event-level wrapper. Saves a single event mapping. | `{ promo_id }` |\n| `bff_preview_event_promos(p_event_id, p_user_id, p_final_amount, p_items)` | Runs the event promo calculator for an event order preview | Freebies, bill discounts, total discount, adjusted amount |\n| `bff_toggle_event_promo(p_promo_id, p_is_active)` | Activate/deactivate promo | Updated state |\n| `bff_delete_event_promo(p_promo_id)` | Deletes only promos without claims | Error `PROMO_HAS_CLAIMS` if claims exist |\n| `bff_report_event_promos(p_from, p_to, p_frequency, p_filters)` | Admin report. Filters: `promo_id`, `event_id`, `outcome_type`, `tier_id`. | Summary, time series, promo/rule/outcome breakdowns |\n| `bff_report_event_promos_rows(p_from, p_to, p_filters, p_limit, p_offset, p_sort)` | Admin report drilldown. Sorts: `created_at_desc`, `created_at_asc`, `quantity_desc`, `member_name_asc`. | Claim rows and `total_count` |\n| Function | Purpose |\n|---|---|\n| `fn_calc_event_promos(p_merchant_id, p_event_id, p_user_id, p_final_amount, p_items)` | Applies mapped merchant promos for the event. Evaluates rules, loops `event_promo_rule_outcome` rows in `outcome_order`, applies freebies, free rewards, bill discounts, `highest`/`all` modes, and total/per-event claim limits. |\n| `fn_apply_event_promos(p_merchant_id, p_transaction_id, p_user_id, p_promo_result)` | Inserts freebie purchase items, records event-aware promo claims, and applies bill discounts to `purchase_ledger`. |\n| `fn_evaluate_promo_condition(p_condition, p_items, p_final_amount)` | Evaluates condition JSON: `product_qty_threshold`, `spend_threshold`, `product_combo`, and compound `AND`/`OR`. |\n**Tables:**\n|---|---|\n| `event_promo` | Merchant-level promo definition. `event_id` is nullable legacy scope. New claim limit fields are `max_claims_per_user_total` and `max_claims_per_user_per_event`. |\n| `event_promo_rule` | Ordered conditions for a promo. Legacy flat `outcome_*` fields remain for one release and mirror the first child outcome. |\n| `event_promo_rule_outcome` | Ordered outcomes for a rule. Outcomes: `freebie`, `free_reward`, `bill_discount_pct`, `bill_discount_fixed`. Unique by `(rule_id, outcome_order)`. |\n| `event_promo_mapping` | Scope table for where a merchant promo applies. `mapping_type=''event''` uses `event_id`; `mapping_type=''activity_group''` uses `activity_group`. |\n| `event_promo_claim` | Claim ledger. Includes `event_id` so per-event limits can be enforced. Unique rule-level claim index supports multiple rules from the same promo in one transaction. |\n**Key Business Rules:**\n\n- Promotions are merchant-owned. Events and activity groups are applicability mappings, not promo owners.\n- A promo applies to an event when the event is directly mapped or the event''s `activity_group` matches a mapped activity group.\n- Save activity-group mappings as activity groups, not as expanded event IDs, so future events in that group inherit the promo.\n- `max_claims_per_user_total` limits the user across all mapped events for the promo.\n- `max_claims_per_user_per_event` limits the user separately within each event.\n- If both limits are set, both must have remaining capacity before the promo can apply.\n- `eval_mode=''highest''` applies the highest ordered passing rule only, then stops after that rule''s outcomes.\n- `eval_mode=''all''` applies every passing rule until claim limits are exhausted.\n- Outcomes on a qualifying rule are applied in `outcome_order`.\n- Total/per-event claim limits are per-rule budgets. Freebie/free reward outcomes consume emitted quantity; bill discounts consume one claim unit.", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/event-promotion.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "event-promotion", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "4be5e9b15ebf0dfbd600f6a4d919194248c07505b4172ef91be30a9d66fc924d", "truncated": false}, "is_active": true}, {"id": "c8549cee-d6ab-55e0-b38e-a6f235fa3fe5", "feature_slug": "forms", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map:**\n\n| Page Name | Current Route | BFF / Data Source |\n|---|---|---|\n| Profile Form Settings | `/user-profile-form-settings` | `bff_admin_get_user_profile_config`, `bff_admin_upsert_user_profile_config` |\n| Consent & Communication Settings | `/consent-settings` | `loadConsentConfig()`, consent save action |\n\n### 4a. Configure Default Fields\n\n1. Open **Profile Form Settings** — page loads with two sections: Default Fields and Custom Fields\n2. Each default field appears as a collapsible card showing: label, field_key tag, active/inactive badge, and summary (Required, Visible user/admin, Editable, Personas)\n3. Click **\"Edit\"** on a field card to expand — configure: Required, Visible to user, Visible to admin, Editable by user checkboxes\n4. If personas exist, a **Persona requirement** multi-select appears — leave empty for all personas, or select specific ones to restrict\n5. Use **arrow buttons** to reorder fields — position determines display order in signup form\n6. Click **\"Disable\"/\"Enable\"** to toggle `active_status` — disabled fields disappear from the member form\n7. Click **\"Save\"** in page header — normalizes order indexes and submits via `bff_admin_upsert_user_profile_config`\n\n### 4b. Configure Custom Fields\n\n1. In **Profile Form Settings**, scroll to the Custom Fields section\n2. Click **\"Add group\"** to create a field group — set group name, group key, and optionally enable \"Require at least one field\"\n3. Within a group, click **\"Add Field\"** — configure: label, field_key, field type (free_text/single_select/multi_select), placeholder, required, persona filter\n4. For select fields: an **Options** sub-section appears — add options with value, label, default flag, and reorder with arrows\n5. Use arrow buttons to reorder groups and fields within groups\n6. Click **\"Save\"** — entire config (default + custom) saves atomically\n\n### 4c. Configure PDPA / Consent\n\n1. Open **Consent & Communication Settings** — separate page for consent configuration\n2. Configure consent items: privacy notices, marketing opt-ins, communication channels, topics\n3. Set interaction type (notice/optional/required) and mandatory flag per consent item\n\n### 4d. Common Admin Mistakes\n\n- Creating custom fields but leaving the USER_PROFILE form template in `draft` status → fields don''t appear on signup\n- Setting `persona_ids` on a field when no personas are configured → field hidden from all members\n- Making a field required but not visible to user → form submission fails\n- Forgetting to save after reordering → changes lost on page refresh\n- Adding a new required field post-launch → returning members see `complete_profile_existing` flow with missing fields only", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/forms.md#L88 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "91f772ae7e29b20123e49b5a3dcefaf7f62ce5be3f1630164622f8bf66c3934c", "truncated": false}, "is_active": true}, {"id": "fe6e8fb3-cf78-5f17-b3d7-5ba3fcbf694d", "feature_slug": "forms", "title": "Conditional Field Logic", "content": "Conditions enable dynamic form behavior based on user input.\n\n### Condition Components\n\n\n| Component          | Purpose                            |\n| ------------------ | ---------------------------------- |\n| `source_field_key` | Field being monitored              |\n| `operator`         | Comparison logic                   |\n| `compare_value`    | Value to match against             |\n| `target_field_key` | Field whose behavior changes       |\n| `action_type`      | What happens when condition is met |\n\n\n### Operators\n\n- `equals` / `not_equals` - exact match\n- `contains` / `not_contains` - substring\n- `greater_than` / `less_than` - numeric\n- `is_empty` / `is_not_empty` - presence check\n\n### Action Types\n\n- `show` / `hide` - visibility\n- `enable` / `disable` - interactivity\n- `require` - make mandatory\n\n### Example\n\n```\nsource_field_key: \"occupation\"\noperator: \"equals\"\ncompare_value: \"student\"\ntarget_field_key: \"income_range\"\naction_type: \"hide\"\n```\n\nWhen occupation = \"student\", hide income_range field.\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Forms.md#L347 Conditional Field Logic", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "4142f659b4496cf255df24bb975993151c726a2e9aac5995479c3670deb89af2", "truncated": false}, "is_active": true}, {"id": "c1cced1e-2b82-5616-bc9a-65e94981d6b3", "feature_slug": "forms", "title": "Survey Submission Limits", "content": "Survey forms (non-USER_PROFILE) support per-user and total submission limits via the shared `transaction_limits` infrastructure.\n\n### How it works\n\n- `transaction_limits` rows with `entity_type = ''form''` and `entity_id = <form_template UUID>` define limits\n- `scope = ''user''` → per-user limit; `scope = ''total''` → global cap across all users\n- `time_unit` options: `day`, `week`, `month`, `year`, `all_time`\n- `count` = maximum allowed submissions within the time window\n\n### Enforcement\n\n`submit_form_public` calls `fn_check_form_submission_limits(p_user_id, p_form_id, p_merchant_id)` before accepting a submission. Limits are skipped for:\n\n- USER_PROFILE forms (always unlimited)\n- Anonymous submissions (`p_user_id IS NULL`) — per-user limits cannot apply without an identified user\n\n### Error response when limit exceeded\n\n```json\n{\n  \"success\": false,\n  \"title\": \"Submission limit reached\",\n  \"description\": \"You have reached the maximum of 3 submissions per month for this form\",\n  \"data\": {\n    \"error_code\": \"FORM_LIMIT_EXCEEDED\",\n    \"limit_scope\": \"user\",\n    \"limit_time_unit\": \"month\",\n    \"current_count\": 3,\n    \"max_allowed\": 3,\n    \"next_available_at\": \"2026-05-01T00:00:00Z\"\n  }\n}\n```\n\n### Functions\n\n\n| Function                          | Type    | Purpose                                                                                        |\n| --------------------------------- | ------- | ---------------------------------------------------------------------------------------------- |\n| `fn_check_form_submission_limits` | Backend | Check per-user/total submission limits against `transaction_limits` where `entity_type=''form''` |\n| `submit_form_public`              | API     | Submit survey form — now enforces limits before validation and insert                          |", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Forms.md#L762 Survey Submission Limits", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "b9f3741bc79d07f51634e21ba6cc00258336b8a03b9c77345857c2785b27f680", "truncated": false}, "is_active": true}, {"id": "42f546b6-31c9-5bff-9eeb-969bb299fc65", "feature_slug": "forms", "title": "7. Business Rules", "content": "**Rule:** Two-system architecture — default fields write to `user_accounts`/`user_address` columns; custom fields write to `form_responses` via a `form_submission` record. Both save atomically through `bff_save_user_profile`.\n**Example:** Saving a form with email (default) and occupation (custom) → email updates `user_accounts.email`, occupation creates/updates a `form_responses` row linked to the USER_PROFILE submission.\n\n**Rule:** Persona selection during signup determines which fields are visible. Fields with `persona_ids` containing the selected persona (or `persona_ids = null`) appear; others are filtered out.\n**Example:** \"Company Name\" field has `persona_ids = [\"corporate-uuid\"]`. Member selects \"Individual\" persona → field not shown.\n\n**Rule:** Conditional field logic evaluates client-side in real-time. When a source field''s value matches the condition''s operator + compare_value, the action is applied to the target field.\n**Example:** Source \"has_children\" equals \"yes\" → action \"show\" on \"number_of_children\" field.\n\n**Rule:** `form_step` auto-skips steps with no content. If a merchant has no personas, the persona step is skipped. If no custom fields exist, the custom_field step is skipped.\n**Example:** Merchant with only default fields and PDPA → member sees: default_field → pdpa (two steps).\n\n**Rule:** Cache has 5-minute TTL for form structure. User values are always fetched live. Structure cached in Redis via `extensions.user_profile_cache_set`.\n**Example:** Admin adds a new field → members may see old structure for up to 5 minutes. Values submitted against the new field are still saved correctly.\n\n**Rule:** The `bff-auth-complete` edge function fetches the form template using an anon Supabase client (no user JWT) with explicit `p_merchant_code`. This is necessary because the custom JWT''s `sub` is a `user_accounts.id`, not an `auth.users` UUID.\n**Example:** After OTP verification, the edge function loads the form before the user JWT is available.\n\n**Rule:** \"Accept All\" in PDPA sets `isAccepted = true` on all consent sections and `selected = true` on all sub-options. Individual option toggles update the master checkbox (true only when all children are selected).\n**Example:** Member unchecks \"SMS\" in communication channels → master \"Communication Channels\" checkbox unchecks.\n\n**Rule:** Empty `persona_ids` (null or []) means unrestricted — all members see the field. Setting `persona_ids` to specific UUIDs restricts to those personas only.\n**Example:** Field with `persona_ids = null` → visible to Corporate, SME, and Individual personas alike.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/forms.md#L245 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "8590ca352a892fcbf88abac184242f93ca84d4c3f1e9242cbadae119c2098b80", "truncated": false}, "is_active": true}, {"id": "252e50c9-3210-5ae6-97b0-0335ed136c00", "feature_slug": "forms", "title": "3. Configuration Reference", "content": "### Default Field Settings\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| field_label | Display label | \"Email Address\" | field_key name |\n| field_type | Input component type | `email`, `phone`, `date`, `select`, `normal` | `normal` |\n| placeholder | Placeholder text | \"Enter your email\" | None |\n| help_text | Guidance below field | \"We''ll send updates here\" | None |\n| order_index | Display order (0-based) | 0 | Sequential |\n| is_required | Mandatory for submission | true | false |\n| visible_to_user | Member sees this field | true | true |\n| visible_to_admin | Admin sees in profile view | true | true |\n| editable_by_user | Member can modify value | true | true |\n| active_status | Field is enabled | true | true |\n| validation_pattern | Regex for input validation | `^[0-9]{13}$` | None |\n| min_length / max_length | Character limits | 2 / 100 | None |\n| options | Choices for select-type fields (JSONB) | `[{\"value\":\"male\",\"label\":\"Male\"}]` | None |\n| persona_ids | Restrict to specific personas | `[\"uuid1\",\"uuid2\"]` | null (all) |\n\n### Custom Field Settings\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| field_key | Unique machine identifier | \"occupation\" | Required |\n| field_type | Input type | `free_text`, `single_select`, `multi_select` | Required |\n| text_format | Sub-type for free_text | `text`, `email`, `phone`, `number`, `date`, `multiline` | `text` |\n| label | Display label | \"What is your occupation?\" | Required |\n| is_required | Mandatory for submission | true | false |\n| persona_ids | Restrict to specific personas | `[\"uuid1\"]` | null (all) |\n| options | Choices for select fields | `[{\"value\":\"fashion\",\"label\":\"Fashion\"}]` | [] |\n| conditions | Conditional logic rules | See Key Concepts | [] |\n\n### Field Group Settings\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| group_key | Unique identifier | \"preferences\" | Required |\n| group_name | Display heading | \"Your Interests\" | Required |\n| order_index | Group display order | 0 | Sequential |\n| require_at_least_one | At least one field must be filled | true | false |\n\n### PDPA Consent Settings\n\n| Setting | What it controls | Example |\n|---|---|---|\n| consent_type | Category | `privacy_policy`, `marketing` |\n| interaction_type → `notice` | Read-only display, no action needed | Privacy policy text |\n| interaction_type → `optional` / `required` | Checkbox consent (type: `text_content`) | Marketing opt-in |\n| type: `checkbox_options` | Multiple sub-checkboxes | Communication channels (email, SMS, LINE, push) |\n| is_mandatory | Must accept to proceed | true for required consents |", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/forms.md#L35 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "dd12ed3e85da8dc5ac50ba55bbe31765093a71260db27f3a6ad22342183d2dca", "truncated": false}, "is_active": true}, {"id": "4c60904e-c99d-5dd2-92cc-762854e97fdc", "feature_slug": "forms", "title": "API Functions", "content": "### GET Template\n\n```\nPOST /rest/v1/rpc/bff_get_user_profile_template\n\nParameters:\n- p_language: \"en\" | \"th\" (default: \"en\")\n- p_mode: \"new\" | \"edit\" (default: \"new\")\n\nHeaders:\n- Authorization: Bearer {jwt}\n- x-merchant-id: {uuid} (optional, extracted from JWT if not provided)\n```\n\n**Mode Behavior:**\n\n\n| Mode   | Structure  | Values                               |\n| ------ | ---------- | ------------------------------------ |\n| `new`  | From cache | All `null`                           |\n| `edit` | From cache | From database for authenticated user |\n\n\n**Response Structure:**\n\n```json\n{\n  \"selected_section\": null,\n  \"default_fields_config\": [{\n    \"id\": \"default-fields-group\",\n    \"group_key\": \"default_fields\",\n    \"group_name\": \"ข้อมูลพื้นฐาน\",\n    \"fields\": [{\n      \"id\": \"uuid\",\n      \"field_key\": \"email\",\n      \"field_type\": \"email\",\n      \"label\": \"Email Address\",\n      \"value\": null,\n      \"options\": [],\n      \"is_required\": true,\n      \"is_address_field\": false,\n      \"persona_ids\": null,\n      \"conditions\": []\n    }]\n  }],\n  \"custom_fields_config\": [{\n    \"id\": \"uuid\",\n    \"group_key\": \"preferences\",\n    \"group_name\": \"ความสนใจ\",\n    \"fields\": [{\n      \"id\": \"uuid\",\n      \"field_key\": \"interests\",\n      \"field_type\": \"multi-select\",\n      \"label\": \"สิ่งที่สนใจ\",\n      \"value\": null,\n      \"options\": [{\n        \"id\": \"uuid\",\n        \"option_value\": \"fashion\",\n        \"option_label\": \"แฟชั่น\"\n      }],\n      \"conditions\": [{\n        \"source_field_key\": \"occupation\",\n        \"operator\": \"equals\",\n        \"compare_value\": \"student\",\n        \"action_type\": \"hide\"\n      }]\n    }]\n  }],\n  \"persona\": {\n    \"selected_persona_id\": null,\n    \"merchant_config\": { \"persona_attain\": \"pre-form\" },\n    \"persona_groups\": [...]\n  },\n  \"pdpa\": [{\n    \"id\": \"uuid\",\n    \"consent_type\": \"privacy_policy\",\n    \"interaction_type\": \"notice\",\n    \"type\": \"notice\",\n    \"title\": \"นโยบายความเป็นส่วนตัว\",\n    \"content\": \"...\",\n    \"isAccepted\": false,\n    \"requires_action\": false,\n    \"is_mandatory\": false,\n    \"options\": []\n  }, {\n    \"id\": \"channels\",\n    \"type\": \"checkbox_options\",\n    \"title\": \"ช่องทางการติดต่อ\",\n    \"isAccepted\": false,\n    \"options\": [\n      { \"id\": \"email\", \"label\": \"อีเมล\", \"selected\": false },\n      { \"id\": \"sms\", \"label\": \"SMS\", \"selected\": false },\n      { \"id\": \"line\", \"label\": \"LINE\", \"selected\": false },\n      { \"id\": \"push\", \"label\": \"การแจ้งเตือน\", \"selected\": false }\n    ]\n  }],\n  \"mode\": \"new\",\n  \"cache_hit\": true,\n  \"language\": \"th\",\n  \"timestamp\": \"2025-12-07T...\"\n}\n```\n\n### SAVE Profile\n\n```\nPOST /rest/v1/rpc/bff_save_user_profile\n\nParameters:\n- p_data: Full payload from bff_get_user_profile_template with user-filled values\n\nHeaders:\n- Authorization: Bearer {jwt}\n```\n\n**What it saves:**\n\n\n| Data                   | Destination                                  |\n| ---------------------- | -------------------------------------------- |\n| Default fields         | `user_accounts` (UPSERT)                     |\n| Address fields         | `user_address` (UPSERT)                      |\n| `selected_persona_id`  | `user_accounts.persona_id`                   |\n| Custom fields          | `form_responses` via USER_PROFILE submission |\n| Consent acceptance     | `user_consent_ledger`                        |\n| Communication channels | `user_accounts.channel`_* flags              |\n| Communication topics   | `user_communication_preferences`             |\n\n\n**Response:**\n\n```json\n{\n  \"success\": true,\n  \"user_id\": \"uuid\",\n  \"is_new_user\": false\n}\n```\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Forms.md#L423 API Functions", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a8844ff0ef3c11cf23ec8534ed95bba56994057ff2d1fae9227d5d23f7116de0", "truncated": false}, "is_active": true}, {"id": "f4a19172-6dfc-5dd2-a2c3-e7351ffa3fa6", "feature_slug": "forms", "title": "Database Schema Summary", "content": "```\n┌─────────────────────┐      ┌──────────────────────┐\n│  user_field_config  │      │    form_templates    │\n│  (default fields)   │      │   (custom fields)    │\n└─────────────────────┘      └──────────────────────┘\n         │                            │\n         │                   ┌────────┴────────┐\n         │                   │                 │\n         ▼              ┌────▼─────┐    ┌──────▼──────┐\n┌─────────────────┐    │form_field│    │form_conditions│\n│  user_accounts  │    │ _groups  │    └──────────────┘\n│  user_address   │    └────┬─────┘\n└─────────────────┘         │\n                       ┌────▼─────┐\n                       │form_fields│\n                       └────┬─────┘\n                            │\n                       ┌────▼──────────┐\n                       │form_field_    │\n                       │   options     │\n                       └───────────────┘\n\n┌─────────────────────┐     ┌─────────────────────┐\n│  form_submissions   │────▶│   form_responses    │\n│  (one per user)     │     │  (one per field)    │\n└─────────────────────┘     └─────────────────────┘\n```\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Forms.md#L711 Database Schema Summary", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "63e49bbfede51dd228d2f9821941c8b456ee9c5017263828bdf15d9f8b9da79f", "truncated": false}, "is_active": true}, {"id": "ae11cf4c-4720-5884-9a09-d616fe408761", "feature_slug": "forms", "title": "2. Key Concepts", "content": "**Default Field** — A standard profile field backed by a real database column (e.g., `email` in `user_accounts`, `city` in `user_address`). Configured per-merchant via `user_field_config` with settings for visibility, editability, validation, and persona filtering. There are 15 possible default fields (email, phone, firstname, lastname, fullname, birth_date, id_card, line_id, gender, plus 6 address fields).\n\n**Custom Field** — A merchant-defined field stored in the `form_responses` table. Three types: `free_text` (with format variants: text, email, phone, number, date, multiline), `single_select`, and `multi_select`. Each field has a unique `field_key` used in conditional logic.\n\n**Form Template** — A container for custom fields. The special template with `code = ''USER_PROFILE''` holds the signup/profile form. One per merchant. Must have `status = ''published''` to be active. Statuses: `draft`, `published`, `archived`.\n\n**Field Group** — An organizational unit within a form template. Groups have a `group_key`, display name, ordering, and an optional `require_at_least_one` validation rule. Example: \"Employment Info\", \"Preferences\".\n\n**Field Type** — Determines how a custom field renders. `free_text` uses `text_format` to select the input variant (text input, email keyboard, phone with country code, number pad, date calendar, multiline textarea). `single_select` and `multi_select` render as bottom-sheet pickers with options from `form_field_options`.\n\n**Conditional Field Logic** — Rules that change field behavior based on other field values. A condition links a `source_field_key` (monitored field) to a `target_field_key` (affected field) via an operator and action. Example: when `occupation` equals `\"student\"`, hide the `income_range` field.\n\n**Operator** — Comparison logic for conditions: `equals`, `not_equals`, `contains`, `is_empty`, `is_not_empty`, `greater_than`, `less_than`.\n\n**Action Type** — What happens when a condition matches: `show`, `hide` (visibility), `enable`, `disable` (interactivity), `require` (make mandatory).\n\n**PDPA Consent** — Privacy/data-protection consent items shown during signup. Three interaction types: `notice` (read-only text, no checkbox), `text_content` (single checkbox — optional or mandatory), `checkbox_options` (master checkbox with individual sub-options for channels/topics).\n\n**Form Step** — Frontend-only navigation state for the multi-step signup form. Sequence: `persona` → `default_field` → `custom_field` → `pdpa`. Steps with no content are automatically skipped.\n\n**Persona-Aware Field** — A field with `persona_ids` set to specific persona UUIDs. Only members with a matching persona see this field. `persona_ids = null` or `[]` means visible to all.", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/forms.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "1f05310bbdcf9fbb940ad176c061da8ee8b7a31a07df0320beb210954781b9bd", "truncated": false}, "is_active": true}]'::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id,
  feature_item_id,
  title,
  content,
  content_format,
  knowledge_type,
  perspectives,
  output_uses,
  scope,
  source_ref,
  metadata,
  is_active,
  now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
